mapper.sql:
FROM appointment_slot s
JOIN doctor_schedule ds ON ds.id = s.schedule_id
JOIN doctor dr ON dr.id = ds.doctor_id
JOIN department d ON d.id = dr.department_id
WHERE s.status = 'AVAILABLE'
AND ds.status = 'OPEN'
AND dr.status = 'ACTIVE'
AND d.status = 'ACTIVE'
AND s.start_at > #{now}
AND ds.schedule_date BETWEEN #{from} AND #{until}
AND s.id = #{slotId}
AND d.id = #{criteria.departmentId}
AND dr.id = #{criteria.doctorId}
AND (d.name = #{criteria.departmentName} OR d.code = #{criteria.departmentName})
AND dr.name = #{criteria.doctorName}
AND ds.schedule_date = #{criteria.appointmentDate}
AND ds.clinic_period = #{criteria.clinicPeriod}
